# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÜÇGENDE İÇ VE DIŞ AÇILARIN ÖZELLİKLERİ VE İSPATI (MAT.9.3.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PARALEL DOĞRU İLE İÇ AÇILAR İSPATI</text>\n  <line x1="60" y1="95" x2="290" y2="95" stroke="#dc2626" stroke-width="2" stroke-dasharray="5,3"/>\n  <text x="298" y="99" font-size="10.5" font-weight="bold" fill="#dc2626">d₁ // [BC]</text>\n  <polygon points="175,95 85,190 265,190" fill="#dbeafe" stroke="#1e3a8a" stroke-width="2.5"/>\n  <text x="175" y="86" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">A</text>\n  <text x="72" y="195" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">B</text>\n  <text x="278" y="195" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">C</text>\n  <text x="175" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">a</text>\n  <text x="112" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">b</text>\n  <text x="238" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">c</text>\n  <text x="142" y="110" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">b (İç ters)</text>\n  <text x="210" y="110" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">c (İç ters)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Doğru açı: a + b + c = 180°</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">TEMEL AÇI BAĞINTILARI</text>\n  <text x="378" y="96" font-size="11" font-weight="bold" fill="#14532d">1. İç Açılar Toplamı:</text>\n  <text x="378" y="114" font-size="11" font-weight="bold" fill="#166534">   m(A) + m(B) + m(C) = 180°</text>\n  <text x="378" y="142" font-size="11" font-weight="bold" fill="#14532d">2. Dış Açılar Toplamı:</text>\n  <text x="378" y="160" font-size="11" font-weight="bold" fill="#166534">   a\' + b\' + c\' = 360°</text>\n  <text x="378" y="188" font-size="11" font-weight="bold" fill="#b91c1c">3. Bir Dış Açı Özelliği (Çok Önemli!):</text>\n  <text x="378" y="206" font-size="10.5" font-weight="bold" fill="#7f1d1d">   Bir dış açı, kendisine komşu olmayan</text>\n  <text x="378" y="222" font-size="10.5" font-weight="bold" fill="#7f1d1d">   iki iç açının toplamına eşittir: c\' = a + b</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKİZKENAR VE EŞKENAR ÜÇGEN ÖZELLİKLERİ (MAT.9.3.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">İKİZKENAR ÜÇGEN (|AB| = |AC|)</text>\n  <polygon points="180,82 105,185 255,185" fill="#fef3c7" stroke="#b45309" stroke-width="2.5"/>\n  <line x1="180" y1="82" x2="180" y2="185" stroke="#dc2626" stroke-width="2" stroke-dasharray="4,3"/>\n  <rect x="180" y="175" width="10" height="10" fill="none" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="180" y="76" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">A (Tepe)</text>\n  <text x="92" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">B</text>\n  <text x="268" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">C</text>\n  <text x="180" y="199" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">H (Orta Nokta)</text>\n  <text x="38" y="216" font-size="10.5" font-weight="bold" fill="#78350f">• Taban açıları eşittir: m(B) = m(C) = (180° - m(A)) / 2</text>\n  <text x="38" y="232" font-size="10.5" font-weight="bold" fill="#b91c1c">• İNDİRİLEN DİKME (AH): Hem Açıortay hem Kenarortaydır!</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">EŞKENAR ÜÇGEN (|AB| = |BC| = |AC| = a)</text>\n  <polygon points="520,82 445,185 595,185" fill="#f3e8ff" stroke="#7e22ce" stroke-width="2.5"/>\n  <text x="520" y="110" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#581c87">60°</text>\n  <text x="470" y="178" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#581c87">60°</text>\n  <text x="570" y="178" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#581c87">60°</text>\n  <text x="378" y="206" font-size="10.5" font-weight="bold" fill="#581c87">• Üç kenar uzunluğu birbirine eşit, iç açıları 60°\'dir.</text>\n  <text x="378" y="224" font-size="10.5" font-weight="bold" fill="#581c87">• Üç köşeden çizilen yükseklik, açıortay ve kenarortay</text>\n  <text x="378" y="238" font-size="10" fill="#6b21a8">  uzunlukları birbirine eşittir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÜÇGENDE AÇI-KENAR BAĞINTILARI VE ÜÇGEN EŞİTSİZLİĞİ (MAT.9.3.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. BÜYÜK AÇI - BÜYÜK KENAR İLİŞKİSİ</text>\n  <text x="35" y="96" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Bir üçgende büyük açının karşısında uzun kenar,</text>\n  <text x="35" y="114" font-size="10.5" font-weight="bold" fill="#1e3a8a">  küçük açının karşısında kısa kenar bulunur:</text>\n  <rect x="35" y="130" width="290" height="44" rx="8" fill="#ffffff" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="180" y="157" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">m(A) &gt; m(B) &gt; m(C)  ⇔  a &gt; b &gt; c</text>\n  <text x="35" y="198" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Dik üçgende en uzun kenar HİPOTENÜS (90° karşısı),</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#1d4ed8">  geniş açılı üçgende geniş açının karşısındaki kenardır.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">2. ÜÇGEN EŞİTSİZLİĞİ TEOREMİ</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Herhangi bir kenarın uzunluğu; diğer iki kenarın</text>\n  <text x="375" y="114" font-size="10.5" font-weight="bold" fill="#7f1d1d">  toplamından KÜÇÜK, farklarının mutlak değerinden</text>\n  <text x="375" y="132" font-size="10.5" font-weight="bold" fill="#7f1d1d">  BÜYÜKTÜR:</text>\n  <rect x="375" y="146" width="290" height="58" rx="8" fill="#ffffff" stroke="#fca5a5" stroke-width="1.5"/>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">|b - c| &lt; a &lt; b + c</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">|a - c| &lt; b &lt; a + c   |   |a - b| &lt; c &lt; a + b</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0f172a">Bu koşulu sağlamayan uzunluklarla üçgen çizilemez!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
